    std::string line;
    while (std::getline(file, line)) {
        std::transform(line.begin(), line.end(), line.begin(), ::tolower); // Преобразовать все символы строки в нижний регистр

        std::size_t pos = 0;
        while ((pos = line.find(word, pos)) != std::string::npos) {
            ++count;
            pos += word.length(); // Переходить к следующему вхождению слова
        }
    }

    file.close();

    std::cout << "The word \"" << word << "\" appears " << count << " times in " << filename << "." << std::endl;

    return 0;
}
